"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[14318],{14318:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-kind-worth-killing.png\\"\\n          title=\\"죽여 마땅한 사람들\\"\\n          author=\\"피터 스완슨\\"\\n          publisher=\\"푸른숲\\"\\n          publishedDate=\\"2016-07-22\\"\\n          isbn=\\"9791156756552\\"\\n          rating=4\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n책을 읽으며 정말 ```죽여 마땅한 사람들```의 인물들이지만, 과연 그렇다고 살인을 정당화할 수 있는가를 생각하게 되었다.  \\n그렇다면 법의 심판을 통해 죽인다면 그건 정당화할 수 있고, 그들은 정말로 ```죽여 마땅한 사람들```이었던 걸까?  \\n그럼 죽여 마땅한 사람들이 있다는 것이고, 이것을 판단하는 근거가 개인이 아닌 다수의 동의와 약속이라면 죽일 수 있다는 것인가?  \\n여러 생각을 할 수 있는 책이었다.  \\n<br>\\n배신과 반전이 예상치 못한 결과로 이어진다.  \\n인간 내면에 도사린 욕망과 기만, 자기합리화의 과정을 서늘하게 파고든다.  \\n<br>\\n이 작품 마지막에 열린 결말로 끝나는 게 마음에 들었다.  \\n갑자기 환경운동가가 된 어머니와 한밤중에 소리를 지르며 잠에서 깼다든지, 무슨 일이 있어도 너를 사랑한다는 아버지의 말에서 어느 정도 예상이 되긴 한다.  \\n그래도 독자에게 조금의 여지를 남겨주며 마무리하였다.  "}')}}]);